      ''([(^${pkgs.getconf}/bin/getconf DARWIN_USER_TEMP_DIR | str trim) "agenix" "${name}"] | path join)''
    else
      ''([$env.XDG_RUNTIME_DIR "agenix" "${name}"] | path join)'';
  readAgeSecret =
